    public static GUPPriceComponentCode findName(Name _codeName, boolean _update = false)
    {
        GUPPriceComponentCode  priceComponentCode;

        priceComponentCode.selectForUpdate(_update);

        if (_codeName)
        {
            select firstonly priceComponentCode
                where priceComponentCode.Name == _codeName;
        }

        return priceComponentCode;
    }

    public static GUPPriceComponentCode find(RecId _recId, boolean _update = false)
    {
        GUPPriceComponentCode  priceComponentCode;

        priceComponentCode.selectForUpdate(_update);

        if (_recId)
        {
            select firstonly priceComponentCode
                where priceComponentCode.RecId == _recId;
        }

        return priceComponentCode;
    }

    private boolean checkComponentCode()
    {
        boolean ret = true;

        if (this.PriceComponent == GUPPriceComponent::BasePriceInventoryPrice ||
            this.PriceComponent == GUPPriceComponent::SalesTradeAgreement     ||
            this.PriceComponent == GUPPriceComponent::BasePricePurchasePrice  ||
            this.PriceComponent == GUPPriceComponent::BasePriceSalesPrice     ||
            this.PriceComponent == GUPPriceComponent::PurhcaseTradeAgreement  ||
            this.PriceComponent == GUPPriceComponent::RebateManagement)
        {
            GUPPriceComponentCode priceComponentCode;

            select firstonly RecId from priceComponentCode where
                priceComponentCode.PriceComponent == this.PriceComponent
                    && priceComponentCode.RecId != this.RecId;

            if (priceComponentCode.RecId)
            {
                ret = checkFailed("@GlobalUnifiedPricing:PriceComponentCodeAlreadyExistsError");
            }
        }

        return ret;
    }

    private boolean checkCombinationsWithAllGroup()
    {
        boolean ret = true;
        
        if (this.MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate)
        {
            if (!this.HeaderPriceAttributeGroupAllEnabled && this.orig().HeaderPriceAttributeGroupAllEnabled)
            {
                ret = this.checkAllGroupForPriceDiscTable() && this.checkAllHeaderGroupForPriceAdjustment();
            }

            if(ret && !this.LinePriceAttributeGroupAllEnabled && this.orig().LinePriceAttributeGroupAllEnabled)
            {
                ret = this.checkAllGroupForPriceDiscTable(false) && this.checkAllLineGroupForPriceAdjustmentLine();
            }
            return ret;
        }

        if (!this.HeaderPriceAttributeGroupAllEnabled)
        {
            GUPPriceComponentCodePriceAttributeGroupCombination combination;

            select firstonly RecId from combination 
                where combination.PriceComponentCode == this.RecId
                    && combination.HeaderGroupAll == GUPGroupAll::All;

            if (combination.RecId)
            {
                ret = checkFailed("@GlobalUnifiedPricing:GUPPriceComponentCodeCombinationCannotDisableHeaderAll");
            }

        }

        if (!this.LinePriceAttributeGroupAllEnabled)
        {
            GUPPriceComponentCodePriceAttributeGroupCombination combination;

            select firstonly RecId from combination
                where combination.PriceComponentCode == this.RecId
                    && combination.LineGroupAll == GUPGroupAll::All;

            if (combination.RecId)
            {
                ret = checkFailed("@GlobalUnifiedPricing:GUPPriceComponentCodeCombinationCannotDisableLineAll");
            }

        }
    
        return ret;
    }

    private boolean checkAllGroupForPriceDiscTable(boolean _isForHeader = true)
    {
        boolean ret = true;

        if (this.PriceComponent == GUPPriceComponent::SalesTradeAgreement)
        {
            PriceDiscTable priceDiscTable;
            GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
            
            select firstonly RecId from priceDiscTable
                join RecId from groupCombination
                where PriceDiscTable.PriceComponentCombination == groupCombination.RecId
                    && ((!_isForHeader && groupCombination.LineGroupAll == GUPGroupAll::All)
                        || (_isForHeader && groupCombination.HeaderGroupAll == GUPGroupAll::All));

            if (priceDiscTable.RecId)
            {
                if (_isForHeader)
                {
                    ret = checkFailed("@GlobalUnifiedPricing:AllHeaderCannotBeDisabledForPirceDiscTable");
                }
                else
                {
                    ret = checkFailed("@GlobalUnifiedPricing:AllLineCannotBeDisabledForPirceDiscTable");
                }
            }
        }

        return ret;
    }

    private boolean checkAllHeaderGroupForPriceAdjustment()
    {
        boolean ret = true;

        if (this.PriceComponent == GUPPriceComponent::PriceMarginComponentAdjustment)
        {
            RetailPeriodicDiscount periodicDiscount;
            select firstonly RecId from periodicDiscount
                where periodicDiscount.PriceComponentCode == this.RecId
                    && periodicDiscount.HeaderPricingGroupCode == GUPGroupAll::All;
            if (periodicDiscount.RecId)
            {
                ret = checkFailed("@GlobalUnifiedPricing:AllHeaderCannotBeDisabledForPirceAdjustment");
            }
        }

        return ret;
    }

    private boolean checkAllLineGroupForPriceAdjustmentLine()
    {
        boolean ret = true;

        if (this.PriceComponent == GUPPriceComponent::PriceMarginComponentAdjustment)
        {
            RetailPeriodicDiscountLine periodicDiscountLine;
            GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

            select firstonly RecId from groupCombination
                join periodicDiscountLine
                where periodicDiscountLine.PriceAttributeGroupCombinationRecId == groupCombination.RecId
                    && groupCombination.PriceComponentCode == this.RecId
                    && groupCombination.LineGroupAll == GUPGroupAll::All;
            if (groupCombination.RecId)
            {
                ret = checkFailed("@GlobalUnifiedPricing:AllLineCannotBeDisabledForPirceAdjustmentLine");
            }
        }

        return ret;
    }

    public boolean validateWrite()
    {
        boolean ret = super();
        
        ret = ret && this.checkComponentCode();
        ret = ret && this.checkCombinationsWithAllGroup();

        return ret;
    }

    private void createGroupCombinationsOnHeaderGroupAllEnabled()
    {
        GUPPriceComponentCodePriceAttributeGroupSelection   groupSelection;
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

        while select RecId, PriceAttributeGroup from groupSelection
            where groupSelection.PriceComponentCode == this.RecId
                && groupSelection.SourceLevel == GUPPricingAttributeSourceLevel::Line
        {
            groupCombination.PriceComponentCode                  = this.RecId;
            groupCombination.HeaderGroupAll                      = GUPGroupAll::All;
            groupCombination.LineGroupAll                        = GUPGroupAll::Group;
            groupCombination.LinePriceAttributeGroup             = groupSelection.PriceAttributeGroup;
            groupCombination.insert();
        }
    }

    private void createGroupCombinationsOnLineGroupAllEnabled()
    {
        GUPPriceComponentCodePriceAttributeGroupSelection   groupSelection;
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

        while select RecId, PriceAttributeGroup from groupSelection
            where groupSelection.PriceComponentCode == this.RecId
                && groupSelection.SourceLevel == GUPPricingAttributeSourceLevel::Header
        {
            groupCombination.PriceComponentCode                  = this.RecId;
            groupCombination.HeaderGroupAll                      = GUPGroupAll::Group;
            groupCombination.HeaderPriceAttributeGroup           = groupSelection.PriceAttributeGroup;
            groupCombination.LineGroupAll                        = GUPGroupAll::All;
            groupCombination.insert();
        }
    }

    private void removeGroupCombinationsOnHeaderGroupAllDisabled()
    {
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

        delete_from groupCombination
            where groupCombination.HeaderGroupAll == GUPGroupAll::All
                && groupCombination.PriceComponentCode == this.RecId;
    }

    private void removeGroupCombinationsOnLineGroupAllDisabled()
    {
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

        delete_from groupCombination
            where groupCombination.LineGroupAll == GUPGroupAll::All
                && groupCombination.PriceComponentCode == this.RecId;
    }

    private void updateGroupCombinationsOnGroupAllChange()
    {
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

        boolean headerAllEnabled  = !this.orig().HeaderPriceAttributeGroupAllEnabled  &&  this.HeaderPriceAttributeGroupAllEnabled;
        boolean headerAllDisabled =  this.orig().HeaderPriceAttributeGroupAllEnabled  && !this.HeaderPriceAttributeGroupAllEnabled;
        boolean lineAllEnabled    = !this.orig().LinePriceAttributeGroupAllEnabled    &&  this.LinePriceAttributeGroupAllEnabled;
        boolean lineAllDisabled   =  this.orig().LinePriceAttributeGroupAllEnabled    && !this.LinePriceAttributeGroupAllEnabled;

        // Only create combinations when header/line priorities are separately assigned.
        if (headerAllEnabled && this.MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate)
        {
            this.createGroupCombinationsOnHeaderGroupAllEnabled();
        }
        else if (headerAllDisabled)
        {
            this.removeGroupCombinationsOnHeaderGroupAllDisabled();
        }

        if (lineAllEnabled && this.MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate)
        {
            this.createGroupCombinationsOnLineGroupAllEnabled();
        }
        else if (lineAllDisabled)
        {
            this.removeGroupCombinationsOnLineGroupAllDisabled();
        }

        if ( (headerAllEnabled || lineAllEnabled) &&
                this.HeaderPriceAttributeGroupAllEnabled &&
                this.LinePriceAttributeGroupAllEnabled &&
                this.MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate)
        {
            // A combination with "all" for both header AND line must be inserted.
            groupCombination.PriceComponentCode         = this.RecId;
            groupCombination.HeaderGroupAll             = GUPGroupAll::All;
            groupCombination.LineGroupAll               = GUPGroupAll::All;
            groupCombination.insert();
        }
    }

    private void updateGroupCombinationsOnNewRecord()
    {
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

        if (this.HeaderPriceAttributeGroupAllEnabled && this.LinePriceAttributeGroupAllEnabled)
        {
            groupCombination.PriceComponentCode         = this.RecId;
            groupCombination.HeaderGroupAll             = GUPGroupAll::All;
            groupCombination.LineGroupAll               = GUPGroupAll::All;
            groupCombination.insert();
        }
    }

    public void update()
    {
        ttsbegin;

        this.updateGroupCombinationsOnGroupAllChange();
        GUPPriceEngineJournalSearchEngine::expirePriority();
        super();

        ttscommit;
    }

    public void insert()
    {
        ttsbegin;

        super();

        if (this.MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate)
        {
            this.updateGroupCombinationsOnNewRecord();
            GUPPriceEngineJournalSearchEngine::expirePriority();
        }

        ttscommit;
    }
